129	/* Narrows [*x0, *x1] on TinyGL buffer row y to what the panel shows. */
130	static bool visible_part(int y, int *x0, int *x1) {
131	  if (!glshim_span_x0) return *x0 <= *x1;
132	  if (*x0 < glshim_span_x0[y]) *x0 = glshim_span_x0[y];
