137	/* Two pixels at a time. `p` is 16-bit and not always 4-byte aligned, so one
138	 * pixel is written first if needed; memcpy then writes each pair without
139	 * reading the memory through a differently typed pointer (strict aliasing),
140	 * and the alignment hint lets it compile to one 32-bit store. */
141	static void fill_pixels(uint16_t *p, uint16_t v, int n) {
142	  if (n > 0 && ((uintptr_t)p & 2)) {
143	    *p++ = v;
144	    n--;
145	  }
146	  const uint32_t pair = ((uint32_t)v << 16) | v;
147	  uint16_t *a = __builtin_assume_aligned(p, 4);
148	  for (; n >= 2; n -= 2, a += 2) memcpy(a, &pair, sizeof pair);
149	  if (n) *a = v;
150	}
