156	/* With the depth test off nothing reads the depth buffer, so a clear that asks
157	 * for it waits until the test is switched on (glshim_depth_test_changed).
158	 * g_z_box keeps growing meanwhile: the rasteriser still writes depth. */
159	static void clear_depth(ZBuffer *zb, GLint z) {
160	  g_depth_clears++;
161	  const Box area = g_z_valid && z == g_clear_z ? g_z_box : whole_canvas();
162	  for (int y = area.y0; y <= area.y1; y++) {
163	    int x0 = area.x0, x1 = area.x1;
164	    if (visible_part(y, &x0, &x1))
165	      fill_pixels((uint16_t *)(zb->zbuf + y * zb->xsize) + x0, (uint16_t)z, x1 - x0 + 1);
166	  }
167	  g_z_box = kEmptyBox;
168	  g_z_valid = true;
169	  g_clear_z = z;
170	}
