247	/* The canvas's disc at TinyGL's size. False only if an allocation fails. */
248	static bool set_spans(const Canvas *canvas) {
249	  if (!canvas->vis_x0) return true;
250	  if (g_scale == 1) {
251	    glshim_span_x0 = canvas->vis_x0;
252	    glshim_span_x1 = canvas->vis_x1;
253	    return true;
254	  }
255	  const int h = g_zb->ysize;
256	  g_half_spans = malloc(2 * (size_t)h * sizeof(int16_t));
257	  if (!g_half_spans) return false;
258	  int16_t *x0s = g_half_spans, *x1s = g_half_spans + h;
259	  for (int y = 0; y < h; y++) {
260	    int lo = INT16_MAX, hi = -1, a0, a1;
261	    for (int r = 2 * y; r <= 2 * y + 1; r++)
262	      if (canvas_visible_span(canvas, r, &a0, &a1)) {
263	        if (a0 < lo) lo = a0;
264	        if (a1 > hi) hi = a1;
265	      }
266	    x0s[y] = (int16_t)(hi < 0 ? 1 : lo / 2);
267	    x1s[y] = (int16_t)(hi < 0 ? 0 : hi / 2);
268	  }
269	  glshim_span_x0 = x0s;
270	  glshim_span_x1 = x1s;
271	  return true;
272	}
