280	  g_zb = scale == 2 ? ZB_open(canvas->w / 2, canvas->h / 2, ZB_MODE_5R6G5B, NULL)
281	                    : ZB_open(canvas->w, canvas->h, ZB_MODE_5R6G5B, canvas->px);
282	  if (!g_zb) return NULL;
