332	void glXSwapBuffers(Display *dpy, GLXDrawable drawable) {
333	  (void)dpy;
334	  (void)drawable;
335	  if (!g_canvas) return;
336	  if (g_scale == 2) {
337	    double_into_canvas();
338	    return;
339	  }
340	  const Box boxes[2] = {g_swap_erased, g_swap_drawn};
341	  for (int i = 0; i < 2; i++)
342	    if (!box_empty(boxes[i]))
343	      canvas_mark_dirty(g_canvas, boxes[i].x0, boxes[i].y0,
344	                        boxes[i].x1 - boxes[i].x0 + 1,
345	                        boxes[i].y1 - boxes[i].y0 + 1);
346	  g_swap_drawn = g_swap_erased = kEmptyBox;
347	#ifdef GL_PROFILE
348	  glshim_prof_frames++;
349	#endif
350	}
