526	static void cross3(const float a[3], const float b[3], float out[3]) {
527	  out[0] = a[1] * b[2] - a[2] * b[1];
528	  out[1] = a[2] * b[0] - a[0] * b[2];
529	  out[2] = a[0] * b[1] - a[1] * b[0];
530	}
