558	    case GL_RGB: bytes = 3; break;
559	    case GL_RGBA: bytes = 4; break;
560	    case GL_LUMINANCE: bytes = 1; break;
561	    case GL_LUMINANCE_ALPHA: bytes = 2; break;
562	    default: return;
563	  }
564	  if (type != GL_UNSIGNED_BYTE || width <= 0 || height <= 0 || !pixels) return;
565	  const size_t n = (size_t)width * (size_t)height;
566	  GLubyte *rgb = malloc(n * 3);
567	  if (!rgb) return;
568	  const GLubyte *in = pixels;
569	  for (size_t i = 0; i < n; i++, in += bytes) {
570	    rgb[3 * i + 0] = in[0];
571	    rgb[3 * i + 1] = bytes >= 3 ? in[1] : in[0];
572	    rgb[3 * i + 2] = bytes >= 3 ? in[2] : in[0];
573	  }
574	  glTexImage2D(target, level, 3, width, height, border, GL_RGB, GL_UNSIGNED_BYTE, rgb);
575	  free(rgb);
