17	/* Host stand-ins for the device's FreeRTOS primitives. */
18	typedef struct {
19	  pthread_mutex_t m;
20	  pthread_cond_t c;
21	  int n;
22	} Sem;
23	static void *h_sem_create(void) {
24	  Sem *s = calloc(1, sizeof *s);
25	  pthread_mutex_init(&s->m, NULL);
26	  pthread_cond_init(&s->c, NULL);
27	  return s;
28	}
29	static void h_sem_give(void *p) {
30	  Sem *s = p;
31	  pthread_mutex_lock(&s->m);
32	  s->n++;
33	  pthread_cond_signal(&s->c);
34	  pthread_mutex_unlock(&s->m);
35	}
36	static void h_sem_take(void *p) {
37	  Sem *s = p;
38	  pthread_mutex_lock(&s->m);
39	  while (!s->n) pthread_cond_wait(&s->c, &s->m);
40	  s->n--;
41	  pthread_mutex_unlock(&s->m);
42	}
43	static void h_sem_destroy(void *p) { free(p); }
44	typedef struct {
45	  void (*body)(void *);
46	  void *arg;
47	} Boot;
48	static void *boot(void *p) {
49	  Boot b = *(Boot *)p;
50	  free(p);
51	  b.body(b.arg);
52	  return NULL;
53	}
54	static int spawn_fails;
55	static int h_spawn(void (*body)(void *), void *arg) {
56	  if (spawn_fails) return -1;
57	  Boot *b = malloc(sizeof *b);
58	  b->body = body;
59	  b->arg = arg;
60	  pthread_t t;
61	  if (pthread_create(&t, NULL, boot, b)) return -1;
62	  pthread_detach(t);
63	  return 0;
64	}
65	static uint32_t clock_us;
66	static uint32_t h_now_us(void) { return clock_us += 12500; }
67	static const PushOverlapOps kOps = {h_sem_create, h_sem_give, h_sem_take,
68	                                    h_spawn, h_now_us, h_sem_destroy};
