277	static uint32_t disc_hash(const uint16_t *px) {
278	  uint32_t h = 2166136261u;
279	  for (int y = 0; y < BW; y++) {
280	    int x0, x1;
281	    if (!canvas_visible_span(&big, y, &x0, &x1)) continue;
282	    for (int x = x0; x <= x1; x++) h = (h ^ px[(size_t)y * BW + x]) * 16777619u;
283	  }
284	  return h;
285	}
286	
287	static void add_noise(void) {
288	  static uint32_t lcg = 12345;
289	  for (int i = 0; i < BW * BW; i++) {
290	    lcg = lcg * 1664525u + 1013904223u;
291	    big.px[i] = (uint16_t)(lcg >> 16);
292	  }
293	}
