295	static void run_plain(const HackEntry *e, int frames, bool noise, uint32_t *out) {
296	  const HackEntry *const hacks[] = {e};
297	  HackRunner *r = runner_create_with(&big, hacks, 1);
298	  srandom(1);
299	  runner_start(r, 0);
300	  for (int f = 0; f < frames; f++) {
301	    if (noise) add_noise();
302	    runner_step(r);
303	    out[f] = disc_hash(big.px);
304	  }
305	  runner_destroy(r);
306	}
