341	 * what reached the display. */
342	static bool ignores_the_canvas_it_starts_from(const HackEntry *e, int frames) {
343	  uint32_t plain[FRAMES], noisy[FRAMES];
344	  run_plain(e, frames, false, plain);
345	  run_plain(e, frames, true, noisy);
346	  return memcmp(plain, noisy, frames * sizeof plain[0]) == 0;
347	}
348	static bool looks_the_same_through_the_swap(const HackEntry *e, int frames) {
349	  uint32_t plain[FRAMES], swapped[FRAMES];
350	  run_plain(e, frames, false, plain);
351	  run_swapped(e, frames, swapped);
352	  return memcmp(plain, swapped, frames * sizeof plain[0]) == 0;
353	}
