static bool overlayStamping() {
  uint32_t now = millis();
  return overlay_name_visible(&overlay, now) || overlay_badge_visible(&overlay) ||
         (overlay_qr_visible(&overlay) && qrPixels) ||
         overlay_fps_visible(&overlay) || overlay_battery_visible(&overlay);
}

static void present() {
  if (overlapper) {
    const bool eligible =
        g_hacks[runner_index(runner)]->repaints_all && !overlayStamping();
    if (push_overlap_present(overlapper, &canvas, eligible)) {
      overlay_drawn(&overlay, millis());
      lastSyncUs = 0;
      return;
    }
  }
  sinkPx = canvas.px;
  uint32_t now = millis();
  if (overlay_name_visible(&overlay, now))
    stampText(&namePatch, g_hacks[runner_index(runner)]->name, kSize / 2,
              kNameY, &fonts::DejaVu24);
  if (overlay_badge_visible(&overlay))
    stampText(&namePatch, kBadgeName, kSize / 2, kSize / 2,
              &fonts::Font8x8C64, kBadgeScale);
  if (overlay_qr_visible(&overlay) && qrPixels) stampQr(&infoPatch);
  if (overlay_fps_visible(&overlay) || overlay_battery_visible(&overlay)) {
    char text[16];
    if (overlay_fps_visible(&overlay))
      overlay_fps_text(&overlay, text, sizeof text);
    else
      overlay_battery_text(&overlay, text, sizeof text);
    stampText(&infoPatch, text, kSize / 2, kFpsY, &fonts::DejaVu18);
  }
  overlay_drawn(&overlay, now);
  lastSyncUs = 0;
  if (g_hacks[runner_index(runner)]->sync_to_refresh) {
    /* After the overlay is stamped, so stamping does not move the start. */
    const uint32_t syncWaitUs =
        te_sync_wait_us(&teSync, (uint32_t)esp_timer_get_time());
    if (syncWaitUs) delayMicroseconds(syncWaitUs);
    lastSyncUs = syncWaitUs;
  }
#ifdef TE_DIAG
  uint32_t pushT0 = (uint32_t)esp_timer_get_time();
#endif
  /* A synced hack's TE offset was measured for whole rows (issue #68). */
#ifdef PUSH_NO_DISC
  const bool useDisc = false;
#else
  const bool useDisc = !g_hacks[runner_index(runner)]->sync_to_refresh;
#endif
  int pushedRows = push_present(&canvas, pushRows, &pushSink, useDisc);
  rowsPushed += pushedRows;
#ifdef TE_DIAG
  if (pushedRows > 300 && pushCount < kPushLog) {
    pushStart[pushCount] = pushT0;
    pushFlush[pushCount] = flushBeganUs;
    pushEnd[pushCount] = (uint32_t)esp_timer_get_time();
    pushCount++;
  }
#endif
  unstamp(&infoPatch);
  unstamp(&namePatch);
}

/* Whatever started the hack, the name shows again, the rotation countdown
 * restarts and the stats begin afresh. */
/* 64-byte data cache lines make every sequential PSRAM pass, the display push
 * above all, about 14% cheaper (device A/B in .claude/rules/device-display.md).
 * A TE-synced hack keeps the SDK's 32 bytes: its push offset was swept against
 * the old copy time. A hack with many short spans (Discrete, -5% fps) asks for
 * dcache_line32. -DDCACHE_LINE32 keeps 32 bytes for every hack. */
#ifdef DCACHE_LINE32
static const uint32_t kBulkLineBytes = 32;
#else
static const uint32_t kBulkLineBytes = 64;
#endif

static void hackStarted() {
  if (overlapper) push_overlap_reset(overlapper);
  const HackEntry *hack = g_hacks[runner_index(runner)];
  const bool keep32 = hack->sync_to_refresh || hack->dcache_line32;
  dcache_set_line_size(keep32 ? 32 : kBulkLineBytes);
  uint32_t now = millis();
  overlay_hack_started(&overlay, now);
  rotation_reset(&rotation, now);
  resetStats();
}

